<?php declare(strict_types=1); ?>
<div class="portal-grid"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Controlled onboarding</span><h2>Invite supplier contact</h2></div></header><?php if(can('supplier_portal.invite')): ?><form class="form-grid" method="post" action="<?= h(app_url('supplier-portal-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="create_invitation"><input type="hidden" name="supplier_id" value="<?= $selectedSupplierId ?>"><label><span>Contact</span><select name="supplier_contact_id"><option value="0">New contact</option><?php foreach($contacts as $contact): ?><option value="<?= (int)$contact['id'] ?>"><?= h($contact['name'].' · '.$contact['title']) ?></option><?php endforeach; ?></select></label><label><span>Name</span><input name="invited_name" required></label><label><span>Email</span><input type="email" name="email" required></label><label><span>Portal role</span><select name="portal_role"><?php foreach(['account_administrator','sales','order_fulfillment','billing','quality','executive'] as $role): ?><option value="<?= h($role) ?>"><?= h(status_label($role)) ?></option><?php endforeach; ?></select></label><label><span>Expires after</span><select name="expiration_days"><option value="3">3 days</option><option value="7" selected>7 days</option><option value="14">14 days</option><option value="30">30 days</option></select></label><div class="span-2"><button class="button primary">Create invitation</button></div></form><?php endif; ?></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Invitation ledger</span><h2>Pending and historical invitations</h2></div></header><div class="compact-list"><?php foreach(array_filter($invitations,static fn(array $r):bool=>(int)$r['supplier_id']===$selectedSupplierId) as $invite): ?><article><div><strong><?= h($invite['invited_name']) ?></strong><small><?= h($invite['email']) ?> · <?= h(status_label($invite['portal_role'])) ?> · Expires <?= h(date_us($invite['expires_at'],true)) ?></small></div><?= badge($invite['status']) ?></article><?php endforeach; ?></div></section></div>
<section class="panel"><header class="panel-head"><div><span class="eyebrow">Supplier identities</span><h2>Accounts and company grants</h2></div></header><div class="portal-queue"><?php foreach(array_filter($accounts,static fn(array $r):bool=>(int)$r['supplier_id']===$selectedSupplierId) as $account): ?><article class="portal-record"><header><div><strong><?= h($account['name']) ?></strong><small><?= h($account['email']) ?> · <?= h(status_label($account['portal_role'])) ?> · Last login <?= h(date_us($account['last_login_at']??'',true)) ?></small></div><?= badge($account['status']) ?></header><?php if(can('supplier_portal.administer')): ?><form class="form-grid" method="post" action="<?= h(app_url('supplier-portal-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="save_grant"><input type="hidden" name="account_id" value="<?= (int)$account['id'] ?>"><label><span>Company grant</span><select name="company_id"><?php foreach(data_permitted_companies() as $company): ?><option value="<?= (int)$company['id'] ?>"><?= h($company['name']) ?></option><?php endforeach; ?></select></label><label><span>Grant status</span><select name="status"><option value="active">Active</option><option value="suspended">Suspended</option><option value="revoked">Revoked</option></select></label><label><span>Starts</span><input type="date" name="starts_at" value="<?= date('Y-m-d') ?>"></label><label><span>Expires</span><input type="date" name="expires_at"></label><div class="span-2 permission-grid"><?php foreach(['acknowledge_po'=>'PO response','submit_asn'=>'ASN','submit_invoice'=>'Invoice','submit_documents'=>'Documents','message'=>'Messages','quality'=>'Quality','sourcing'=>'Sourcing'] as $cap=>$label): ?><label><input type="checkbox" name="can_<?= h($cap) ?>" value="1" checked><?= h($label) ?></label><?php endforeach; ?></div><label class="span-2"><span>Access evidence</span><textarea name="evidence_note" required>Grant is limited to the selected supplier and company relationship.</textarea></label><div class="span-2"><button class="button primary">Save company grant</button></div></form><form method="post" action="<?= h(app_url('supplier-portal-action.php')) ?>" class="filter-bar"><?= csrf_field() ?><input type="hidden" name="action" value="set_account_status"><input type="hidden" name="account_id" value="<?= (int)$account['id'] ?>"><select name="status"><option value="active">Active</option><option value="suspended">Suspend</option><option value="revoked">Revoke</option></select><input name="evidence_note" required placeholder="Status-change evidence"><button class="button secondary">Update account</button></form><?php endif; ?></article><?php endforeach; ?><?php if(!array_filter($accounts,static fn(array $r):bool=>(int)$r['supplier_id']===$selectedSupplierId))render_empty_state('No supplier accounts','Create a controlled invitation for this supplier.'); ?></div></section>
